pub fn glyph(role: Role, code: u21) Glyph {
    const table: []const Glyph = switch (role) {
        .body => &body,
        .title => &title,
        .serif => &serif,
        .caption => &caption,
        .reading => &reading,
    };

    // The pinned tables begin with contiguous printable ASCII. Common UI
    // labels and western metadata need no binary search for each glyph.
    if (code >= 32 and code <= 126) return table[code - 32];
    var lo: usize = 0;
    var hi: usize = table.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (table[mid].code == code) return table[mid];
        if (table[mid].code < code) lo = mid + 1 else hi = mid;
    }
    return table['?' - 32];
}

test "packed glyph masks reconstruct the original atlas exactly" {
    const std = @import("std");
    var reconstructed: std.ArrayList(u8) = .empty;
    defer reconstructed.deinit(std.testing.allocator);
    inline for (.{ body, title, serif, caption, reading }) |table| {
        var previous_code: u21 = 0;
        for (table) |g| {
            try std.testing.expect(g.code > previous_code);
            previous_code = g.code;
            try std.testing.expect(g.ink_x + g.ink_width <= g.width);
            try std.testing.expect(g.ink_y + g.ink_height <= g.height);
            const start = reconstructed.items.len;
            try reconstructed.appendNTimes(std.testing.allocator, 0, @as(usize, g.width) * g.height);
            for (0..g.ink_height) |row| {
                const source = g.offset + row * g.ink_width;
                const destination = start + (g.ink_y + row) * g.width + g.ink_x;
                @memcpy(reconstructed.items[destination..][0..g.ink_width], masks[source..][0..g.ink_width]);
            }
        }
    }
    var actual: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(reconstructed.items, &actual, .{});
    var expected: [32]u8 = undefined;
    _ = try std.fmt.hexToBytes(&expected, "dbadfdf96ad8494f9a350d663a16e85821cb6bae56cd1cd33a94dbbac8780ad1");
    try std.testing.expectEqualSlices(u8, &expected, &actual);
}

test "direct ASCII and sparse Unicode lookup match the pinned glyph tables" {
    const std = @import("std");
    inline for (.{ Role.body, Role.title, Role.serif, Role.caption, Role.reading }, .{ body, title, serif, caption, reading }) |role, table| {
        for (table[0..95], 0..) |g, index| try std.testing.expectEqual(@as(u21, @intCast(index + 32)), g.code);
        for (table) |g| try std.testing.expectEqualDeep(g, glyph(role, g.code));
        for (0..512) |code| {
            var expected = table['?' - 32];
            for (table) |g| if (g.code == code) {
                expected = g;
                break;
            };
            try std.testing.expectEqualDeep(expected, glyph(role, @intCast(code)));
        }
        try std.testing.expectEqualDeep(table['?' - 32], glyph(role, 0x10ffff));
    }
}
